const app=document.querySelector('#app');let db,view='overview',tenantId='t_demo',ownerSession=null,adminSession=null,appointmentMode='list';const today=new Date().toISOString().slice(0,10);try{ownerSession=JSON.parse(sessionStorage.getItem('dakikaProOwner'));adminSession=JSON.parse(sessionStorage.getItem('dakikaProAdmin'));if(ownerSession)tenantId=ownerSession.tenantId}catch{}
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(n||0);
const dateTR=d=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short'}).format(new Date(d+'T12:00:00'));
const api=async(path,method='GET',body)=>{const r=await fetch('/data/'+path,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const text=await r.text();let j;try{j=JSON.parse(text)}catch{throw Error('Sunucu yanıtı alınamadı. Lütfen sayfayı yenileyin.')}if(!r.ok)throw Error(j.error||'İşlem yapılamadı');return j};
const defaultFeatures={starter:['Online randevu sayfası','2 çalışan','Hizmet ve müşteri yönetimi','Temel randevu takvimi'],pro:['Başlangıç’taki her şey','8 çalışan','Randevu durumu yönetimi','Müşteri geçmişi ve notlar','Öncelikli destek'],business:['Profesyonel’deki her şey','30 çalışan','Çok şubeli yapıya hazır altyapı','Gelişmiş raporlama','Özel destek']};
const featuresOf=p=>(p.features&&p.features.length?p.features:defaultFeatures[p.id]||[`En fazla ${p.staffLimit} çalışan`]);
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
async function reload(){db=await api('bootstrap');render()}
function nav(){return `<aside class="sidebar"><div class="brand">Dakika<span>Pro</span></div><div class="role">Platform yönetimi</div>${[['overview','Genel Bakış'],['tenants','İşletmeler'],['plans','Üyelik Paketleri'],['finance','Gelir & Abonelikler'],['reports','Raporlar'],['settings','Platform Ayarları']].map(x=>`<button class="nav ${view===x[0]?'active':''}" onclick="go('${x[0]}')">${x[1]}</button>`).join('')}<div class="sidebottom"><button class="nav" onclick="adminLogout()">Çıkış yap</button></div></aside>`}
function header(){let t=db.tenants.find(x=>x.id===tenantId),isOwner=location.hash==='#business'&&ownerSession,person=isOwner?ownerSession.owner.name:'Serkan Y.',role=isOwner?'İşletme Sahibi':'Super Admin',initials=person.split(' ').map(x=>x[0]).join('').slice(0,2);let titles={overview:['Platforma genel bakış','İşletmelerinizi ve büyümenizi tek yerden takip edin.'],tenants:['İşletmeler','Tüm kiracıları, denemeleri ve abonelikleri yönetin.'],plans:['Üyelik paketleri','Fiyatları ve kapasite limitlerini anında düzenleyin.'],finance:['Gelir ve abonelikler','Gelir görünümü, paket tercihleri ve deneme dönüşümlerini takip edin.'],reports:['Platform raporları','Sektör dağılımı ve operasyon sağlığı.'],settings:['Platform ayarları','Deneme süresini ve temel platform kurallarını yönetin.'],business:[t?.name||'İşletme',['Bugünün takvimi ve işletme performansı.']],appointments:['Randevular','Takvimi ve randevu durumlarını yönetin.'],staff:['Çalışanlar','Ekibinizi ve müsaitliklerini düzenleyin.'],services:['Hizmetler','Müşterilerinizin seçebileceği hizmetleri oluşturun.'],customers:['Müşteriler','Müşteri ilişkilerinizi tek yerde saklayın.'],businessAnalytics:['İşletme analitiği','Randevu, gelir ve hizmet performansınızı izleyin.'],businessSettings:['İşletme ve randevu sayfası','Müşterilerin göreceği bilgileri düzenleyin.'],subscription:['Üyelik paketim','İhtiyacınıza uygun paketi seçin.']}[view]||['Panel',''];return `<div class="top"><div><h1>${titles[0]}</h1><p>${Array.isArray(titles[1])?titles[1][0]:titles[1]}</p></div><div class="profile"><div class="avatar">${esc(initials)}</div><div>${esc(person)}<span class="sub">${role}</span></div></div></div>`}
function status(s){const x={active:'Aktif',trial:'Demo',inactive:'Pasif',confirmed:'Onaylandı',pending:'Bekliyor',cancelled:'İptal'}[s]||s;return `<span class="pill ${s}">${x}</span>`}
function overview(){const active=db.tenants.filter(t=>t.status==='active').length,trial=db.tenants.filter(t=>t.status==='trial').length,revenue=db.tenants.filter(t=>t.status==='active').reduce((a,t)=>{let p=db.plans.find(p=>p.id===t.planId);return a+(t.billingCycle==='yearly'?(p?.yearlyPrice||0)/12:(p?.price||0))},0);return `<div class="grid stats"><div class="card stat"><div class="label">Toplam işletme</div><div class="number">${db.tenants.length}</div><div class="delta">Platformdaki tüm işletmeler</div></div><div class="card stat"><div class="label">Aktif abonelik</div><div class="number">${active}</div><div class="delta">Gelir üreten hesaplar</div></div><div class="card stat"><div class="label">Demo işletme</div><div class="number">${trial}</div><div class="delta">${db.settings.trialDays} gün deneme</div></div><div class="card stat"><div class="label">Tahmini aylık gelir</div><div class="number">${fmt(revenue)}</div><div class="delta">Aktif paketlerin aylık karşılığı</div></div></div><div class="grid split"><section class="card"><h2>Abonelik görünümü</h2>${db.plans.map(p=>`<div class="listitem"><div><b>${esc(p.name)}</b><span class="sub">${p.staffLimit} çalışana kadar</span></div><span class="pill">${db.tenants.filter(t=>t.planId===p.id).length} işletme</span></div>`).join('')}</section><section class="card"><h2>Yaklaşan deneme bitişleri</h2>${db.tenants.filter(t=>t.status==='trial').map(t=>`<div class="listitem"><div><b>${esc(t.name)}</b><span class="sub">${dateTR(t.trialEndsAt)} tarihinde sona erer</span></div>${status('trial')}</div>`).join('')||'<p class="sub">Yaklaşan deneme bulunmuyor.</p>'}</section></div>`}
function tenants(){return `<section class="card"><div class="toolbar"><div><h2>İşletme listesi</h2><span class="sub">İşletme bilgileri, paketler ve abonelik durumları burada yönetilir.</span></div><button class="btn" onclick="tenantModal()">+ Yeni işletme</button></div><div class="tablewrap"><table class="table"><thead><tr><th>İşletme</th><th>Sektör</th><th>Paket</th><th>Ödeme dönemi</th><th>Durum</th><th></th></tr></thead><tbody>${db.tenants.map(t=>`<tr><td><span class="name">${esc(t.name)}</span><span class="sub">${esc(t.phone||'Telefon yok')}</span></td><td>${esc(t.sector)}</td><td>${esc(db.plans.find(p=>p.id===t.planId)?.name||'—')}</td><td>${t.billingCycle==='yearly'?'Yıllık':'Aylık'}</td><td>${status(t.status)}</td><td class="actions"><button class="iconbtn" onclick="editTenantModal('${t.id}')">Düzenle</button><button class="iconbtn" onclick="toggleTenant('${t.id}')">${t.status==='inactive'?'Aktifleştir':'Pasifleştir'}</button><button class="iconbtn danger" onclick="deleteTenant('${t.id}','${esc(t.name)}')">Sil</button></td></tr>`).join('')}</tbody></table></div></section>`}
function plans(){return `<section class="card"><div class="toolbar"><div><h2>Paket tanımları</h2><span class="sub">Değişiklikler yeni ve mevcut aboneliklere anında yansır.</span></div><button class="btn" onclick="planModal()">+ Paket ekle</button></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(210px,1fr))">${db.plans.map(p=>`<article class="card" style="box-shadow:none;border-color:${p.featured?'#a5b4fc':'var(--line)'}"><div class="pill ${p.featured?'':'trial'}">${p.featured?'En çok tercih edilen':'Paket'}</div><h2 style="margin-top:13px">${esc(p.name)}</h2><div class="number" style="font:800 25px 'Plus Jakarta Sans'">${fmt(p.price)}<small style="font-size:12px;color:var(--muted)"> / ay</small></div><p class="sub"><b>${fmt(p.yearlyPrice||p.price*10)} / yıl</b> · 2 ay avantajlı<br>En fazla ${p.staffLimit} çalışan</p><ul class="featurelist">${featuresOf(p).map(f=>`<li>✓ ${esc(f)}</li>`).join('')}</ul><button class="btn ghost" style="width:100%;margin-top:14px" onclick="planModal('${p.id}')">Düzenle</button></article>`).join('')}</div></section>`}
function settings(){let s=db.settings;return `<div class="settings"><section class="card"><h2>Genel platform ayarları</h2><p class="sub">Yeni hesaplara ve sistem genelindeki iletişimlere uygulanır.</p><form class="form" onsubmit="saveSettings(event)"><label class="field full">Platform adı<input required name="platformName" value="${esc(s.platformName)}"></label><label class="field">Ücretsiz deneme (gün)<input required type="number" min="1" name="trialDays" value="${s.trialDays}"></label><label class="field">Destek e-postası<input required type="email" name="supportEmail" value="${esc(s.supportEmail||'')}"></label><label class="field">Para birimi<select name="currency"><option ${s.currency==='TRY'?'selected':''}>TRY</option><option ${s.currency==='USD'?'selected':''}>USD</option><option ${s.currency==='EUR'?'selected':''}>EUR</option></select></label><label class="field">Ödeme sağlayıcısı<select name="paymentProvider"><option ${s.paymentProvider==='iyzico'?'selected':''}>iyzico</option><option ${s.paymentProvider==='Stripe'?'selected':''}>Stripe</option><option ${s.paymentProvider==='PayTR'?'selected':''}>PayTR</option></select></label><label class="field full">Bakım modu<select name="maintenanceMode"><option value="false" ${!s.maintenanceMode?'selected':''}>Kapalı</option><option value="true" ${s.maintenanceMode?'selected':''}>Açık — yalnızca yönetim erişir</option></select></label><div class="modalfoot field full"><button class="btn">Ayarları kaydet</button></div></form></section><section class="card"><h2>Bildirim merkezi</h2><p class="sub">Canlı sistemde e-posta/SMS sağlayıcısı bağlandığında otomasyonlar bu ayarlara göre çalışır.</p><form class="form" onsubmit="saveNotificationSettings(event)">${[['trial','Deneme bitiş uyarıları'],['payment','Ödeme/abonelik uyarıları'],['appointment','Randevu uyarıları']].map(x=>`<label class="field full"><span>${x[1]}</span><select name="${x[0]}"><option value="true" ${(s.notifications||{})[x[0]]?'selected':''}>Açık</option><option value="false" ${!(s.notifications||{})[x[0]]?'selected':''}>Kapalı</option></select></label>`).join('')}<div class="modalfoot field full"><button class="btn ghost">Bildirimleri kaydet</button></div></form></section></div>`}
function finance(){let active=db.tenants.filter(t=>t.status==='active'),monthly=active.reduce((sum,t)=>{let p=db.plans.find(x=>x.id===t.planId);return sum+(t.billingCycle==='yearly'?(p?.yearlyPrice||0)/12:(p?.price||0))},0),trial=db.tenants.filter(t=>t.status==='trial');return `<div class="grid stats"><div class="card stat"><div class="label">Aylık tekrar eden gelir</div><div class="number">${fmt(monthly)}</div><div class="delta">Aktif aboneliklerin aylık karşılığı</div></div><div class="card stat"><div class="label">Yıllık sözleşme</div><div class="number">${active.filter(t=>t.billingCycle==='yearly').length}</div><div class="delta">Yıllık ödeme tercih edenler</div></div><div class="card stat"><div class="label">Dönüşüm fırsatı</div><div class="number">${trial.length}</div><div class="delta">Demo hesabı aktif</div></div><div class="card stat"><div class="label">Ortalama paket</div><div class="number">${active.length?fmt(Math.round(monthly/active.length)):fmt(0)}</div><div class="delta">Aktif işletme başına</div></div></div><section class="card" style="margin-top:18px"><h2>Abonelik takibi</h2><div class="tablewrap"><table class="table"><thead><tr><th>İşletme</th><th>Paket</th><th>Dönem</th><th>Durum</th><th>Aylık karşılık</th></tr></thead><tbody>${db.tenants.map(t=>{let p=db.plans.find(x=>x.id===t.planId);return `<tr><td class="name">${esc(t.name)}</td><td>${esc(p?.name||'—')}</td><td>${t.billingCycle==='yearly'?'Yıllık':'Aylık'}</td><td>${status(t.status)}</td><td>${fmt(t.billingCycle==='yearly'?(p?.yearlyPrice||0)/12:(p?.price||0))}</td></tr>`}).join('')}</tbody></table></div></section>`}
function reports(){let sectors=[...new Set(db.tenants.map(t=>t.sector))],plansSummary=db.plans.map(p=>({name:p.name,count:db.tenants.filter(t=>t.planId===p.id).length}));return `<div class="grid split"><section class="card"><h2>Sektör dağılımı</h2>${sectors.map(s=>{let n=db.tenants.filter(t=>t.sector===s).length;return `<div class="listitem"><b>${esc(s)}</b><span>${n} işletme</span></div>`}).join('')}</section><section class="card"><h2>Paket dağılımı</h2>${plansSummary.map(x=>`<div class="listitem"><b>${esc(x.name)}</b><span class="pill">${x.count} işletme</span></div>`).join('')}</section></div><section class="card" style="margin-top:18px"><h2>Yönetim kontrol listesi</h2><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr))"><div><b>Demo dönüşümü</b><p class="sub">Süresi yaklaşan ${db.tenants.filter(t=>t.status==='trial').length} hesabı takip edin.</p></div><div><b>Pasif işletmeler</b><p class="sub">${db.tenants.filter(t=>t.status==='inactive').length} işletmenin erişimi kapalı.</p></div><div><b>Yıllık abonelikler</b><p class="sub">${db.tenants.filter(t=>t.billingCycle==='yearly').length} işletme yıllık planı seçti.</p></div></div></section>`}
function tdata(){return {t:db.tenants.find(x=>x.id===tenantId),staff:db.staff.filter(x=>x.tenantId===tenantId),services:db.services.filter(x=>x.tenantId===tenantId),customers:db.customers.filter(x=>x.tenantId===tenantId),appointments:db.appointments.filter(x=>x.tenantId===tenantId)}}
function business(){let d=tdata(),count=d.appointments.filter(a=>a.date===today).length;return `<div class="notice">${d.t.status==='trial'?`Demo hesabı ${dateTR(d.t.trialEndsAt)} tarihinde sona eriyor.`:'Aktif aboneliğiniz bulunuyor.'} <button class="link" onclick="${ownerSession?"businessGo('subscription')":"go('tenants')"}">Paketleri görüntüle</button></div><div class="grid stats"><div class="card stat"><div class="label">Bugünkü randevu</div><div class="number">${count}</div><div class="delta">Takvimdeki kayıtlar</div></div><div class="card stat"><div class="label">Toplam müşteri</div><div class="number">${d.customers.length}</div><div class="delta">Kayıtlı müşteri</div></div><div class="card stat"><div class="label">Hizmet sayısı</div><div class="number">${d.services.length}</div><div class="delta">Yayında olan hizmetler</div></div><div class="card stat"><div class="label">Çalışan</div><div class="number">${d.staff.length}</div><div class="delta">${db.plans.find(p=>p.id===d.t.planId)?.staffLimit} kişilik paket</div></div></div><section class="card" style="margin-top:18px"><div class="toolbar"><h2>Bugünün randevuları</h2><button class="btn" onclick="appointmentModal()">+ Randevu oluştur</button></div>${appointmentTable(d.appointments.filter(a=>a.date===today))}</section>`}
function appointmentTable(items){let d=tdata();return `<div class="tablewrap"><table class="table"><thead><tr><th>Saat</th><th>Müşteri</th><th>Hizmet</th><th>Çalışan</th><th>Durum</th><th></th></tr></thead><tbody>${items.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(a=>`<tr><td><b>${a.time}</b><span class="sub">${dateTR(a.date)}</span></td><td>${esc(d.customers.find(c=>c.id===a.customerId)?.name||'Yeni müşteri')}</td><td>${esc(d.services.find(s=>s.id===a.serviceId)?.name||'—')}</td><td>${esc(d.staff.find(s=>s.id===a.staffId)?.name||'—')}</td><td>${status(a.status)}</td><td><button class="iconbtn" onclick="changeAppointment('${a.id}')">${a.status==='confirmed'?'İptal':'Onayla'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="sub">Henüz randevu yok.</td></tr>'}</tbody></table></div>`}
function collection(type){let d=tdata(), config={staff:['Çalışanlar','+ Çalışan ekle',d.staff,['Adı','Unvan'],x=>`<tr><td class="name">${esc(x.name)}</td><td>${esc(x.title)}</td><td>${status(x.active?'active':'inactive')}</td></tr>`],services:['Hizmetler','+ Hizmet ekle',d.services,['Hizmet','Süre','Fiyat'],x=>`<tr><td class="name">${esc(x.name)}</td><td>${x.duration} dk</td><td>${fmt(x.price)}</td></tr>`],customers:['Müşteriler','+ Müşteri ekle',d.customers,['Müşteri','Telefon','Ziyaret'],x=>`<tr><td class="name">${esc(x.name)}</td><td>${esc(x.phone)}</td><td>${x.visits||0}</td></tr>`]}[type];return `<section class="card"><div class="toolbar"><div><h2>${config[0]}</h2><span class="sub">${config[2].length} kayıt</span></div><button class="btn" onclick="entityModal('${type}')">${config[1]}</button></div><div class="tablewrap"><table class="table"><thead><tr>${config[3].map(h=>`<th>${h}</th>`).join('')}<th>Durum</th></tr></thead><tbody>${config[2].map(config[4]).join('')||`<tr><td colspan="4" class="sub">Henüz kayıt yok.</td></tr>`}</tbody></table></div></section>`}
function appointments(){let d=tdata(),days=[...new Set(d.appointments.map(a=>a.date))].sort();return `<section class="card"><div class="toolbar"><div><h2>Randevu kataloğu</h2><span class="sub">Takvim veya liste görünümünde randevularınızı yönetin.</span></div><button class="btn" onclick="appointmentModal()">+ Randevu oluştur</button></div><div class="tabs"><button class="tab ${appointmentMode==='list'?'active':''}" onclick="setAppointmentMode('list')">Liste görünümü</button><button class="tab ${appointmentMode==='calendar'?'active':''}" onclick="setAppointmentMode('calendar')">Takvim görünümü</button></div>${appointmentMode==='list'?appointmentTable(d.appointments):`<div class="calendarGrid">${days.map(day=>`<section class="calendarDay"><div class="calendarDate"><b>${dateTR(day)}</b><span>${d.appointments.filter(a=>a.date===day).length} randevu</span></div>${d.appointments.filter(a=>a.date===day).sort((a,b)=>a.time.localeCompare(b.time)).map(a=>`<div class="calendarEvent ${a.status}"><b>${a.time}</b><span>${esc(d.customers.find(c=>c.id===a.customerId)?.name||'Müşteri')}</span><small>${esc(d.services.find(s=>s.id===a.serviceId)?.name||'Hizmet')} · ${esc(d.staff.find(s=>s.id===a.staffId)?.name||'')}</small></div>`).join('')}</section>`).join('')||'<p class="sub">Takvimde gösterilecek randevu yok.</p>'}</div>`}</section>`}
function customerManagement(){let d=tdata();return `<section class="card"><div class="toolbar"><div><h2>Müşteriler</h2><span class="sub">Telefon, ad veya ziyaret sayısına göre filtreleyin.</span></div><div class="actions"><button class="btn ghost" onclick="exportCustomers()">CSV indir</button><button class="btn" onclick="entityModal('customers')">+ Müşteri ekle</button></div></div><input id="customerFilter" class="customerSearch" oninput="filterCustomers()" placeholder="Müşteri adı veya telefon ara..."><div class="tablewrap"><table class="table"><thead><tr><th>Müşteri</th><th>Telefon</th><th>Ziyaret</th><th>Son randevu</th></tr></thead><tbody id="customerRows">${d.customers.map(c=>{let last=d.appointments.filter(a=>a.customerId===c.id).sort((a,b)=>b.date.localeCompare(a.date))[0];return `<tr data-customer="${esc((c.name+' '+c.phone).toLowerCase())}"><td class="name">${esc(c.name)}</td><td>${esc(c.phone)}</td><td>${c.visits||0}</td><td>${last?`${dateTR(last.date)} · ${last.time}`:'—'}</td></tr>`}).join('')||'<tr><td colspan="4" class="sub">Henüz müşteri yok.</td></tr>'}</tbody></table></div><p id="filterEmpty" class="sub" style="display:none;margin-top:14px">Bu filtreyle eşleşen müşteri bulunamadı.</p></section>`}
function landing(){return `<div class="landing"><nav class="landingnav"><a class="brand dark" href="/">Dakika<span>Pro</span></a><div class="landlinks"><a href="#features">Özellikler</a><a href="#pricing">Paketler</a><a href="#login">İşletme girişi</a><button class="btn" onclick="startTrial()">Ücretsiz dene</button></div></nav><main><section class="hero"><div><div class="eyebrow">Randevu alan tüm işletmeler için</div><h1>Randevularınızı değil, <i>işletmenizi</i> büyütün.</h1><p>Berberden güzellik salonuna, psikologdan pilates stüdyosuna: markanıza ait online randevu sayfasını dakikalar içinde açın.</p><div class="heroactions"><button class="btn big" onclick="startTrial()">30 gün ücretsiz dene</button><a class="btn ghost big" href="#pricing">Paketleri karşılaştır</a></div><small>Kredi kartı gerekmez · İstediğiniz zaman iptal edin</small></div><div class="heroart"><div class="mocktop">● ● ● <b>makas-berber.dakikapro</b></div><div class="mockbody"><div class="mocktitle">Makas Berber</div><div class="mocksub">Online randevu al</div><div class="mockrow">Saç + Sakal <b>500 ₺</b></div><div class="mockrow">Uzman: Ahmet Yılmaz</div><button>Randevu seç</button></div><div class="floatcard"><b>Bugün</b><span>8 randevu</span><strong>₺3.250</strong></div></div></section><section id="features" class="section"><div class="eyebrow">Tek sistem, tüm işletmeniz</div><h2>Dağınık takvimler yerine sade bir çalışma alanı.</h2><div class="benefits"><article><b>⌁</b><h3>Kendi randevu sayfanız</h3><p>Markanıza ait benzersiz bağlantıyı paylaşın; müşteriniz saatini kendisi seçsin.</p></article><article><b>◷</b><h3>Takviminiz hep güncel</h3><p>Çalışan, hizmet ve saat bazında çakışmaları önleyin; tüm randevuları tek ekranda görün.</p></article><article><b>◉</b><h3>Müşteri ilişkileri</h3><p>Müşteri geçmişi ve randevu notlarıyla her ziyareti daha kişisel hale getirin.</p></article></div></section><section id="pricing" class="section pricing"><div class="eyebrow">Şeffaf fiyatlandırma</div><h2>İşletmenizin bugünkü boyutuna göre seçin.</h2><p class="lead">Aylık esneklik veya yıllık ödemede iki aylık avantaj. Büyüdükçe paketinizi istediğiniz zaman değiştirin.</p><div class="pricecards">${db.plans.map(p=>`<article class="pricecard ${p.featured?'featured':''}">${p.featured?'<div class="recommended">En çok tercih edilen</div>':''}<h3>${esc(p.name)}</h3><p class="sub">${p.id==='starter'?'Tek kişi veya küçük ekipler için':p.id==='pro'?'Büyüyen salon ve ekipler için':'Yoğun çalışan işletmeler için'}</p><div class="price">${fmt(p.price)} <small>/ ay</small></div><p class="selection"><b>${fmt(p.yearlyPrice||p.price*10)} / yıl</b> · 2 ay avantajlı<br>${p.staffLimit} çalışana kadar</p><ul class="featurelist">${featuresOf(p).map(f=>`<li>✓ ${esc(f)}</li>`).join('')}</ul><button class="btn ${p.featured?'':'ghost'}" onclick="startTrial('${p.id}')">Bu paketle dene</button></article>`).join('')}</div></section><section class="cta"><h2>İlk online randevu sayfanız 5 dakikada hazır.</h2><button class="btn big" onclick="startTrial()">Ücretsiz demoyu başlat</button></section></main><footer>© 2026 DakikaPro · Randevu işletmelerinin büyüme alanı · <a href="#admin-login">Yönetim</a></footer></div>`}
function landingExtras(){return `<section class="section testimonials"><div class="eyebrow">İşletmeler ne diyor?</div><h2>Randevuları düzenlemek, müşterileri mutlu etmeye alan açtı.</h2><div class="benefits"><article><div class="stars">★★★★★</div><p>“Müşterilerimiz linkten kendi saatini seçmeye başladı. Telefon trafiğimiz ilk haftada ciddi şekilde azaldı.”</p><h3>Ahmet Yılmaz</h3><span class="sub">Makas Berber · İstanbul</span></article><article><div class="stars">★★★★★</div><p>“Ekibin takvimini tek ekranda görmek hayat kurtarıyor. Randevu çakışmalarımız neredeyse bitti.”</p><h3>Elif Demir</h3><span class="sub">Luna Güzellik · İstanbul</span></article><article><div class="stars">★★★★★</div><p>“Küçük bir stüdyo olarak aylık paketle başladık; işletme büyüdükçe paketimizi kolayca yükselttik.”</p><h3>Selin Aras</h3><span class="sub">Denge Pilates · İzmir</span></article></div></section><section id="about" class="section about"><div><div class="eyebrow">Hakkında</div><h2>DakikaPro, hizmet işletmelerinin dijital randevu asistanıdır.</h2></div><div><p>DakikaPro; berber, kuaför, güzellik salonu, klinik, eğitmen ve randevu ile çalışan tüm işletmeler için tasarlanmış çok kiracılı bir yönetim platformudur.</p><p>Amacımız, her işletmenin teknik bilgiye ihtiyaç duymadan kendi markasıyla online randevu alabilmesini ve günlük operasyonlarını tek, sade bir panelden yönetebilmesini sağlamaktır.</p><a class="link" href="#signup/starter">İşletmeni ücretsiz oluştur →</a></div></section>`}
function exampleBusinesses(){return `<section class="section examples"><div class="eyebrow">Örnek işletmeler</div><h2>DakikaPro ile oluşturulmuş sayfaları keşfedin.</h2><p class="lead">Her işletme, kendi markasına ait bağlantıdan müşterilerine online randevu deneyimi sunar.</p><div class="exampleCards">${db.tenants.filter(t=>t.status!=='inactive').map(t=>`<article class="exampleCard" style="--accent:${esc(t.color||'#4f46e5')}"><div class="exampleMark">${esc(t.name.slice(0,1))}</div><div><span class="sub">${esc(t.sector)}</span><h3>${esc(t.name)}</h3><p>${esc(t.address||'Online randevu')}</p><a class="link" href="/#book/${encodeURIComponent(t.slug)}">Randevu sayfasını gör →</a></div></article>`).join('')}</div></section>`}
function signupPage(planId='starter'){let p=db.plans.find(x=>x.id===planId)||db.plans[0];app.innerHTML=`<div class="authpage"><section class="card authcard"><a href="/" class="brand">Dakika<span>Pro</span></a><h1>İşletmenizi ücretsiz oluşturun</h1><p class="sub">${db.settings.trialDays} gün boyunca seçtiğiniz paketin tüm temel özelliklerini deneyin.</p><form class="form" onsubmit="signup(event)"><input type="hidden" name="planId" value="${p.id}"><label class="field full">İşletme adı<input required name="name" placeholder="Örn. Ege Hair Studio"></label><label class="field">Sektör<select name="sector">${['Berber','Kuaför','Güzellik Salonu','Psikolog','Diyetisyen','Pilates / Fitness','Veteriner','Diğer'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">Özel bağlantı<input required name="slug" placeholder="ege-hair-studio"></label><label class="field">Sahip adı<input required name="ownerName" placeholder="Ad soyad"></label><label class="field">Telefon<input required name="phone" placeholder="05xx..."></label><label class="field full">E-posta<input required type="email" name="email" placeholder="ornek@isletme.com"></label><label class="field full">Şifre<input required minlength="6" type="password" name="password" placeholder="En az 6 karakter"></label><label class="field full">Ödeme dönemi<select name="billingCycle"><option value="monthly">Aylık — ${fmt(p.price)} / ay</option><option value="yearly">Yıllık — ${fmt(p.yearlyPrice||p.price*10)} / yıl (2 ay avantajlı)</option></select></label><div class="planchoice field full">Seçilen paket: ${esc(p.name)} · ${p.staffLimit} çalışana kadar</div><div class="modalfoot field full"><a class="btn ghost" href="#login">Zaten hesabım var</a><button class="btn">Demo hesabımı oluştur</button></div></form></section></div>`}
function loginPage(){app.innerHTML=`<div class="authpage"><section class="card authcard"><a href="/" class="brand">Dakika<span>Pro</span></a><h1>İşletme paneline giriş</h1><p class="sub">Kendi işletmenize ait randevuları ve ayarları yönetin.</p><form class="form" onsubmit="ownerLogin(event)"><label class="field full">E-posta<input required type="email" name="email" placeholder="ornek@isletme.com"></label><label class="field full">Şifre<input required type="password" name="password"></label><div class="modalfoot field full"><a class="btn ghost" href="#signup/starter">Hesap oluştur</a><button class="btn">Giriş yap</button></div><button type="button" class="link" onclick="forgotPassword()">Şifrenizi mi unuttunuz?</button><p class="sub field full">Demo giriş: owner@makasberber.com · demo123</p></form></section></div>`}
function adminLoginPage(){app.innerHTML=`<div class="authpage"><section class="card authcard"><a href="/" class="brand">Dakika<span>Pro</span></a><h1>Yönetim girişi</h1><p class="sub">Bu alan yalnızca platform yöneticileri içindir.</p><form class="form" onsubmit="adminLogin(event)"><label class="field full">Yönetici e-posta<input required type="email" name="email"></label><label class="field full">Yönetim şifresi<input required type="password" name="password"></label><div class="modalfoot field full"><a class="btn ghost" href="/">Vazgeç</a><button class="btn">Yönetim paneline gir</button></div><p class="sub field full">Demo: admin@dakikapro.local · admin123</p></form></section></div>`}
function businessNav(){return `<aside class="sidebar business-side"><div class="brand">Dakika<span>Pro</span></div><div class="role">${esc(tdata().t.name)}</div>${[['business','Genel Bakış'],['appointments','Randevular'],['staff','Çalışanlar'],['services','Hizmetler'],['customers','Müşteriler'],['businessAnalytics','Analitik'],['businessSettings','İşletme & Sayfa'],['subscription','Paketim']].map(x=>`<button class="nav ${view===x[0]?'active':''}" onclick="businessGo('${x[0]}')">${x[1]}</button>`).join('')}<div class="sidebottom"><button class="nav" onclick="ownerLogout()">Çıkış yap</button></div></aside>`}
function subscription(){let t=tdata().t;return `<section class="card"><h2>Üyelik paketim</h2><p class="sub">Mevcut planınız: <b>${esc(db.plans.find(p=>p.id===t.planId)?.name||'—')}</b> · ${t.billingCycle==='yearly'?'Yıllık':'Aylık'} · ${t.status==='trial'?'Demo hesabı':'Aktif abonelik'}</p><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(210px,1fr));margin-top:20px">${db.plans.map(p=>`<article class="card" style="box-shadow:none"><h2>${esc(p.name)}</h2><div class="number" style="font:800 23px 'Plus Jakarta Sans'">${fmt(p.price)}<small style="font-size:12px;color:var(--muted)"> / ay</small></div><p class="sub"><b>${fmt(p.yearlyPrice||p.price*10)} / yıl</b> · 2 ay avantajlı</p><ul class="featurelist">${featuresOf(p).map(f=>`<li>✓ ${esc(f)}</li>`).join('')}</ul><div class="actions"><button class="btn ${t.planId===p.id&&t.billingCycle==='monthly'?'ghost':''}" onclick="choosePlan('${p.id}','monthly')">Aylık seç</button><button class="btn ghost" onclick="choosePlan('${p.id}','yearly')">Yıllık seç</button></div></article>`).join('')}</div></section>`}
function renewalOptions(){let s=db.settings,t=tdata().t,p=db.plans.find(x=>x.id===t.planId),amount=t.billingCycle==='yearly'?(p?.yearlyPrice||0):(p?.price||0);return `<section class="card" style="margin-top:18px"><h2>Paket yenileme ve ödeme</h2><p class="sub">DakikaPro yönetimi bu işletme için kullanılabilir ödeme yöntemlerini belirler.</p><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr));margin-top:16px">${s.allowOnlinePayment?`<div class="card" style="box-shadow:none"><b>Online ödeme</b><p class="sub">${esc(s.paymentProvider||'Ödeme sağlayıcısı')} ile güvenli ödeme.</p><button class="btn" onclick="paymentRequest('online',${amount})">${fmt(amount)} ile online yenile</button></div>`:''}${s.allowBankTransfer?`<div class="card" style="box-shadow:none"><b>Havale / nakit ödeme</b><p class="sub">IBAN: ${esc(s.iban||'Yönetim tarafından henüz girilmedi')}</p><p class="sub">Alıcı: ${esc(s.accountHolder||'—')}</p><button class="btn ghost" onclick="paymentRequest('bank',${amount})">Havale bildirimi oluştur</button></div>`:''}</div></section>`}
function paymentSettings(){let s=db.settings;return `<section class="card" style="margin-top:18px"><h2>Ödeme yöntemleri ve IBAN</h2><p class="sub">Bu seçimler firma panelindeki paket yenileme seçeneklerini belirler.</p><form class="form" onsubmit="savePaymentSettings(event)"><label class="field">Online ödeme<select name="allowOnlinePayment"><option value="true" ${s.allowOnlinePayment?'selected':''}>Açık</option><option value="false" ${!s.allowOnlinePayment?'selected':''}>Kapalı</option></select></label><label class="field">Havale / nakit ödeme<select name="allowBankTransfer"><option value="true" ${s.allowBankTransfer?'selected':''}>Açık</option><option value="false" ${!s.allowBankTransfer?'selected':''}>Kapalı</option></select></label><label class="field full">IBAN<input name="iban" value="${esc(s.iban||'')}" placeholder="TR00 0000 0000 0000 0000 0000 00"></label><label class="field full">Hesap sahibi<input name="accountHolder" value="${esc(s.accountHolder||'')}" placeholder="DakikaPro Yazılım A.Ş."></label><div class="modalfoot field full"><button class="btn">Ödeme ayarlarını kaydet</button></div></form></section>`}
function businessAnalytics(){let d=tdata(),done=d.appointments.filter(a=>a.status==='confirmed'),revenue=done.reduce((s,a)=>s+(d.services.find(v=>v.id===a.serviceId)?.price||0),0),upcoming=d.appointments.filter(a=>a.date>=today&&a.status!=='cancelled').length;return `<div class="grid stats"><div class="card stat"><div class="label">Toplam randevu</div><div class="number">${d.appointments.length}</div><div class="delta">Tüm zamanlar</div></div><div class="card stat"><div class="label">Onaylanan randevu</div><div class="number">${done.length}</div><div class="delta">Gerçekleşen / onaylı</div></div><div class="card stat"><div class="label">Tahmini gelir</div><div class="number">${fmt(revenue)}</div><div class="delta">Onaylı hizmet toplamı</div></div><div class="card stat"><div class="label">Yaklaşan randevu</div><div class="number">${upcoming}</div><div class="delta">Bugün ve sonrası</div></div></div><section class="card" style="margin-top:18px"><h2>En çok kullanılan hizmetler</h2>${d.services.map(s=>{let n=d.appointments.filter(a=>a.serviceId===s.id&&a.status!=='cancelled').length;return `<div class="listitem"><div><b>${esc(s.name)}</b><span class="sub">${s.duration} dk · ${fmt(s.price)}</span></div><span class="pill">${n} randevu</span></div>`}).join('')||'<p class="sub">Analiz için önce hizmet ve randevu ekleyin.</p>'}</section>`}
function businessSettings(){let t=tdata().t;return `<div class="settings"><section class="card"><h2>İşletme profili</h2><p class="sub">Müşterilerin göreceği işletme bilgileri.</p><form class="form" onsubmit="saveBusinessSettings(event)"><label class="field full">İşletme adı<input required name="name" value="${esc(t.name)}"></label><label class="field">Sektör<input required name="sector" value="${esc(t.sector)}"></label><label class="field">Telefon<input name="phone" value="${esc(t.phone||'')}"></label><label class="field full">Adres<input name="address" value="${esc(t.address||'')}"></label><label class="field full">Çalışma saatleri<input name="workingHours" value="${esc(t.workingHours||'Pazartesi–Cumartesi, 09:00–19:00')}"></label><div class="modalfoot field full"><button class="btn">Profili kaydet</button></div></form></section><section class="card"><h2>Online randevu sayfanız</h2><p class="sub">Bu bağlantıyı Instagram bio, Google işletme profiliniz veya WhatsApp üzerinden paylaşın.</p><a class="link" target="_blank" href="/#book/${encodeURIComponent(t.slug)}">/#book/${esc(t.slug)}</a><p class="sub" style="margin-top:18px">Müşteriler ayrıca telefon numarasıyla randevularını yönetmek için <b>/#mine/${esc(t.slug)}</b> bağlantısını kullanabilir.</p></section></div>`}
function render(){if(location.hash.startsWith('#display/'))return tvDisplay(location.hash.slice(9));if(location.hash.startsWith('#book/'))return booking(location.hash.slice(6));if(location.hash.startsWith('#mine/'))return myBookings(location.hash.slice(6));if(location.hash.startsWith('#signup/'))return signupPage(location.hash.slice(8));if(location.hash==='#login')return loginPage();if(location.hash==='#admin-login')return adminLoginPage();if(location.hash==='#business'){if(!ownerSession){location.hash='#login';return}let content={business,appointments,staff:()=>collection('staff'),services:()=>collection('services'),customers:customerManagement,businessAnalytics,businessSettings,subscription:()=>subscription()+renewalOptions()}[view]();app.innerHTML=`<div class="shell">${businessNav()}<main class="main">${header()}${content}</main></div>`;return}if(location.hash.startsWith('#admin')&&!adminSession){location.hash='#admin-login';return}if(!location.hash.startsWith('#admin')){app.innerHTML=landing();app.querySelector('.heroart').insertAdjacentHTML('afterbegin','<img class="heroVisual" src="/assets/dakikapro-hero.png" alt="DakikaPro ile dijital randevu yöneten salon sahibi">');app.querySelector('.landing main').insertAdjacentHTML('beforeend',exampleBusinesses()+landingExtras());return}let content={overview,tenants,plans,finance,reports,settings:()=>settings()+paymentSettings()}[view]();app.innerHTML=`<div class="shell">${nav()}<main class="main">${header()}${content}</main></div>`}
function go(v){view=v;location.hash='#admin';render()}function startTrial(planId='starter'){location.hash='#signup/'+planId}function businessGo(v){view=v;location.hash='#business';render()}function selectTenant(id){tenantId=id;view='business';location.hash='#admin';render()}async function toggleTenant(id){let t=db.tenants.find(x=>x.id===id);await api('tenants/'+id,'PATCH',{status:t.status==='inactive'?'active':'inactive'});toast('İşletme durumu güncellendi');reload()}
function setAppointmentMode(mode){appointmentMode=mode;render()}
function filterCustomers(){let q=(document.querySelector('#customerFilter')?.value||'').toLocaleLowerCase('tr-TR'),rows=[...document.querySelectorAll('#customerRows tr[data-customer]')],shown=0;rows.forEach(row=>{let hit=row.dataset.customer.includes(q);row.style.display=hit?'':'none';if(hit)shown++});let empty=document.querySelector('#filterEmpty');if(empty)empty.style.display=shown?'none':''}
function exportCustomers(){let d=tdata(),lines=['Ad Soyad,Telefon,Ziyaret Sayısı,Son Randevu'];d.customers.forEach(c=>{let last=d.appointments.filter(a=>a.customerId===c.id).sort((a,b)=>b.date.localeCompare(a.date))[0];lines.push(`"${String(c.name).replaceAll('"','""')}","${c.phone}",${c.visits||0},"${last?last.date+' '+last.time:''}"`)});let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\n')],{type:'text/csv;charset=utf-8'}));a.download=`${tdata().t.slug}-musteriler.csv`;a.click();URL.revokeObjectURL(a.href);toast('Müşteri listesi CSV olarak indirildi.')}
function modal(html){document.body.insertAdjacentHTML('beforeend',`<div class="modalback" onclick="if(event.target===this)this.remove()"><section class="modal">${html}</section></div>`)}function closeModal(){document.querySelector('.modalback')?.remove()}
function tenantModal(){modal(`<h2>Yeni işletme oluştur</h2><p>İşletme otomatik ${db.settings.trialDays} günlük demo hesabıyla açılır.</p><form class="form" onsubmit="createTenant(event)"><label class="field full">İşletme adı<input required name="name" placeholder="Örn. Ege Hair Studio"></label><label class="field">Sektör<select name="sector">${['Berber','Kuaför','Güzellik Salonu','Psikolog','Diyetisyen','Pilates / Fitness','Veteriner','Diğer'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">Benzersiz bağlantı<input required name="slug" placeholder="ege-hair-studio"></label><label class="field">Paket<select name="planId">${db.plans.map(p=>`<option value="${p.id}">${p.name} — ${fmt(p.price)}</option>`).join('')}</select></label><label class="field">Telefon<input name="phone" placeholder="05xx..."></label><label class="field full">Adres<input name="address" placeholder="İlçe, şehir"></label><div class="modalfoot field full"><button type="button" class="btn ghost" onclick="closeModal()">Vazgeç</button><button class="btn">Demo hesabını aç</button></div></form>`)}
async function createTenant(e){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));try{await api('tenants','POST',o);closeModal();view='tenants';toast('İşletme ve demo hesabı oluşturuldu');reload()}catch(x){toast(x.message)}}
function editTenantModal(id){let t=db.tenants.find(x=>x.id===id);modal(`<h2>İşletmeyi düzenle</h2><p>İşletme bilgileri, abonelik tercihi ve özel yetkiler.</p><form class="form" onsubmit="saveTenant(event,'${id}')"><label class="field full">İşletme adı<input required name="name" value="${esc(t.name)}"></label><label class="field">Sektör<input required name="sector" value="${esc(t.sector)}"></label><label class="field">Telefon<input name="phone" value="${esc(t.phone||'')}"></label><label class="field">Paket<select name="planId">${db.plans.map(p=>`<option value="${p.id}" ${t.planId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Ödeme dönemi<select name="billingCycle"><option value="monthly" ${t.billingCycle!=='yearly'?'selected':''}>Aylık</option><option value="yearly" ${t.billingCycle==='yearly'?'selected':''}>Yıllık</option></select></label><label class="field full">Durum<select name="status"><option value="trial" ${t.status==='trial'?'selected':''}>Demo</option><option value="active" ${t.status==='active'?'selected':''}>Aktif</option><option value="inactive" ${t.status==='inactive'?'selected':''}>Pasif</option></select></label><label class="field full"><span><b>TV randevu panosu</b><small class="sub">Paket dışı özel erişim vermek için açın.</small></span><select name="tvDisplayEnabled"><option value="true" ${t.tvDisplayEnabled!==false?'selected':''}>Açık</option><option value="false" ${t.tvDisplayEnabled===false?'selected':''}>Kapalı</option></select></label><div class="modalfoot field full"><button type="button" class="btn ghost" onclick="closeModal()">Vazgeç</button><button class="btn">Kaydet</button></div></form>`)}
async function saveTenant(e,id){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.tvDisplayEnabled=o.tvDisplayEnabled==='true';await api('tenants/'+id,'PATCH',o);closeModal();toast('İşletme bilgileri güncellendi');reload()}
async function deleteTenant(id,name){if(!confirm(`“${name}” işletmesini ve ilişkili tüm kayıtlarını silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`))return;try{await api('tenants/'+id,'DELETE');toast('İşletme ve ilişkili kayıtlar silindi.');view='tenants';reload()}catch(x){toast(x.message)}}
function planModal(id){let p=db.plans.find(x=>x.id===id)||{};modal(`<h2>${id?'Paketi düzenle':'Yeni paket'}</h2><p>Paket detayları işletmelere anında yansır.</p><form class="form" onsubmit="savePlan(event,'${id||''}')"><label class="field full">Paket adı<input required name="name" value="${esc(p.name||'')}"></label><label class="field">Aylık ücret (₺)<input required min="0" type="number" name="price" value="${p.price||''}"></label><label class="field">Yıllık ücret (₺)<input required min="0" type="number" name="yearlyPrice" value="${p.yearlyPrice||p.price*10||''}"></label><label class="field">Çalışan limiti<input required min="1" type="number" name="staffLimit" value="${p.staffLimit||''}"></label><label class="field full">Paket içerikleri <span class="sub">Her satıra bir özellik yazın.</span><textarea required name="features">${esc(featuresOf(p).join('\n'))}</textarea></label><div class="modalfoot field full"><button type="button" class="btn ghost" onclick="closeModal()">Vazgeç</button><button class="btn">Kaydet</button></div></form>`)}
async function savePlan(e,id){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.price=Number(o.price);o.yearlyPrice=Number(o.yearlyPrice);o.staffLimit=Number(o.staffLimit);o.features=o.features.split('\n').map(x=>x.trim()).filter(Boolean);await api(id?'plans/'+id:'plans',id?'PATCH':'POST',o);closeModal();toast('Paket kaydedildi');reload()}
async function saveSettings(e){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.trialDays=Number(o.trialDays);o.maintenanceMode=o.maintenanceMode==='true';await api('settings','PATCH',o);toast('Platform ayarları kaydedildi');reload()}
async function saveNotificationSettings(e){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));Object.keys(o).forEach(k=>o[k]=o[k]==='true');await api('settings','PATCH',{notifications:o});toast('Bildirim ayarları kaydedildi');reload()}
async function saveBusinessSettings(e){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));await api('tenants/'+tenantId,'PATCH',o);toast('İşletme bilgileri kaydedildi');reload()}
async function savePaymentSettings(e){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.allowOnlinePayment=o.allowOnlinePayment==='true';o.allowBankTransfer=o.allowBankTransfer==='true';await api('settings','PATCH',o);toast('Ödeme ayarları kaydedildi');reload()}
function entityModal(type){let c={staff:['Çalışan ekle','Ad soyad','name','Uzmanlık / unvan','title'],services:['Hizmet ekle','Hizmet adı','name','Süre (dakika)','duration'],customers:['Müşteri ekle','Ad soyad','name','Telefon','phone']}[type];modal(`<h2>${c[0]}</h2><form class="form" onsubmit="createEntity(event,'${type}')"><label class="field full">${c[1]}<input required name="${c[2]}"></label><label class="field">${c[3]}<input required ${type==='services'?'type="number" min="5" value="30"':''} name="${c[4]}"></label>${type==='services'?'<label class="field">Fiyat (₺)<input required type="number" name="price"></label>':''}<div class="modalfoot field full"><button type="button" class="btn ghost" onclick="closeModal()">Vazgeç</button><button class="btn">Ekle</button></div></form>`)}
async function createEntity(e,type){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));if(type==='staff')o.active=true;if(type==='services'){o.active=true;o.price=Number(o.price);o.duration=Number(o.duration)}if(type==='customers')o.visits=0;await api(`tenant/${tenantId}/${type}`,'POST',o);closeModal();toast('Kayıt eklendi');reload()}
function appointmentModal(){let d=tdata();if(!d.staff.length||!d.services.length||!d.customers.length)return toast('Önce en az bir çalışan, hizmet ve müşteri ekleyin.');modal(`<h2>Randevu oluştur</h2><p>Aynı çalışan için aynı tarih ve saatte çakışma oluşturulamaz.</p><form class="form" onsubmit="createAppointment(event)"><label class="field">Müşteri<select name="customerId">${d.customers.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label class="field">Çalışan<select name="staffId">${d.staff.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label class="field">Hizmet<select name="serviceId">${d.services.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.duration} dk</option>`).join('')}</select></label><label class="field">Durum<select name="status"><option value="confirmed">Onaylandı</option><option value="pending">Bekliyor</option></select></label><label class="field">Tarih<input required type="date" name="date" value="${today}"></label><label class="field">Saat<input required type="time" name="time" value="09:00"></label><label class="field full">Not<textarea name="note"></textarea></label><div class="modalfoot field full"><button type="button" class="btn ghost" onclick="closeModal()">Vazgeç</button><button class="btn">Randevu oluştur</button></div></form>`)}
async function createAppointment(e){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));let clash=tdata().appointments.some(a=>a.staffId===o.staffId&&a.date===o.date&&a.time===o.time&&a.status!=='cancelled');if(clash)return toast('Bu çalışan o saatte dolu.');await api(`tenant/${tenantId}/appointments`,'POST',o);closeModal();toast('Randevu oluşturuldu');reload()}
async function changeAppointment(id){let a=db.appointments.find(x=>x.id===id);await api('appointments/'+id,'PATCH',{status:a.status==='confirmed'?'cancelled':'confirmed'});toast('Randevu durumu güncellendi');reload()}
async function signup(e){e.preventDefault();try{let r=await api('auth/signup','POST',Object.fromEntries(new FormData(e.target)));ownerSession={token:r.token,tenantId:r.tenantId,owner:r.owner};sessionStorage.setItem('dakikaProOwner',JSON.stringify(ownerSession));tenantId=r.tenantId;view='business';location.hash='#business';await reload();toast('İşletmeniz oluşturuldu. Demo hesabınız aktif!')}catch(x){toast(x.message)}}
async function ownerLogin(e){e.preventDefault();try{let r=await api('auth/login','POST',Object.fromEntries(new FormData(e.target)));ownerSession={token:r.token,tenantId:r.tenantId,owner:r.owner};sessionStorage.setItem('dakikaProOwner',JSON.stringify(ownerSession));tenantId=r.tenantId;view='business';location.hash='#business';await reload();toast('İşletme paneline hoş geldiniz.')}catch(x){toast(x.message)}}
async function adminLogin(e){e.preventDefault();try{let r=await api('auth/admin-login','POST',Object.fromEntries(new FormData(e.target)));adminSession={token:r.token,admin:r.admin};sessionStorage.setItem('dakikaProAdmin',JSON.stringify(adminSession));view='overview';location.hash='#admin';render();toast('Yönetim paneline hoş geldiniz.')}catch(x){toast(x.message)}}
function ownerLogout(){ownerSession=null;sessionStorage.removeItem('dakikaProOwner');location.hash='#login';toast('Çıkış yapıldı.')}
function adminLogout(){adminSession=null;sessionStorage.removeItem('dakikaProAdmin');location.hash='';toast('Yönetim panelinden çıkış yapıldı.')}
function forgotPassword(){let s=db.settings;alert(`Şifre sıfırlama için DakikaPro destek ekibiyle iletişime geçin.\nE-posta: ${s.supportEmail||'destek@dakikapro.com'}\nTelefon: ${s.supportPhone||'0850 000 00 00'}`)}
function paymentRequest(method,amount){let s=db.settings;if(method==='bank'){alert(`Havale/elden ödeme için yönlendirme:\nIBAN: ${s.iban||'Yönetim IBAN bilgisi girmedi.'}\nHesap sahibi: ${s.accountHolder||'—'}\nTutar: ${fmt(amount)}\nÖdeme sonrasında DakikaPro desteği arayın: ${s.supportPhone||'0850 000 00 00'}`)}else alert(`${fmt(amount)} tutarındaki online yenileme talebiniz hazır. ${s.paymentProvider||'Ödeme sağlayıcısı'} canlı entegrasyonu eklendiğinde güvenli ödeme ekranına yönlendirileceksiniz.`)}
async function choosePlan(planId,billingCycle='monthly'){await api('tenants/'+tenantId,'PATCH',{planId,billingCycle});toast(`${billingCycle==='yearly'?'Yıllık':'Aylık'} paket seçiminiz kaydedildi. Ödeme altyapısı bağlandığında tahsilat adımı burada açılacak.`);await reload()}
async function booking(slug){try{let d=await api('public/'+slug),t=d.tenant;app.innerHTML=`<div class="public"><div class="book"><a href="/" class="link">← DakikaPro</a><header class="bookinghead" style="background:linear-gradient(135deg,${t.color||'#292b68'},#4f46e5)"><div class="bookingnav"><div><h1>${esc(t.name)}</h1><p>${esc(t.sector)} · ${esc(t.address||'Online randevu')}</p></div><a href="/#mine/${encodeURIComponent(t.slug)}" class="mylink">Randevularım</a></div></header><section class="card bookingform"><h2>Online randevu al</h2><p class="sub">Hizmetinizi, saati ve iletişim bilgilerinizi seçin.</p><form class="form" onsubmit="publicBooking(event,'${t.id}')"><label class="field full">Hizmet<select required name="serviceId">${d.services.filter(x=>x.active).map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.duration} dk · ${fmt(s.price)}</option>`).join('')}</select></label><label class="field">Uzman<select name="staffId">${d.staff.filter(x=>x.active).map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.title)}</option>`).join('')}</select></label><label class="field">Tarih<input required type="date" min="${today}" name="date" value="${today}"></label><label class="field">Saat<select name="time">${['09:00','09:30','10:00','10:30','11:00','11:30','13:00','13:30','14:00','14:30','15:00','15:30','16:00','16:30','17:00'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">Ad soyad<input required name="name" placeholder="Adınız soyadınız"></label><label class="field">Telefon<input required name="phone" placeholder="05xx xxx xx xx"></label><div class="modalfoot field full"><button class="btn">Randevu talebi gönder</button></div></form></section></div></div>`}catch(e){app.innerHTML=`<div class="public"><div class="book card"><h2>İşletme bulunamadı</h2><p class="sub">Bu bağlantı geçerli değil veya işletme pasif durumda.</p><a href="/" class="btn">Ana sayfaya dön</a></div></div>`}}
async function myBookings(slug){try{let d=await api('public/'+slug),t=d.tenant;app.innerHTML=`<div class="public"><div class="book"><a href="/#book/${encodeURIComponent(slug)}" class="link">← Randevu al</a><header class="bookinghead" style="background:linear-gradient(135deg,${t.color||'#292b68'},#4f46e5)"><h1>Randevularım</h1><p>${esc(t.name)} için kayıtlı randevularınızı yönetin.</p></header><section class="card bookingform"><h2>Telefon numaranızı girin</h2><p class="sub">Kayıt sırasında kullandığınız numara ile randevularınıza erişebilirsiniz.</p><form class="form" onsubmit="lookupBookings(event,'${esc(slug)}')"><label class="field full">Telefon numarası<input required name="phone" placeholder="05xx xxx xx xx" autocomplete="tel"></label><div class="modalfoot field full"><button class="btn">Randevularımı görüntüle</button></div></form></section></div></div>`}catch(e){toast(e.message)}}
async function lookupBookings(e,slug){e.preventDefault();let phone=new FormData(e.target).get('phone');try{let d=await api(`public/${encodeURIComponent(slug)}/customer?phone=${encodeURIComponent(phone)}`);showBookings(d,phone)}catch(x){toast(x.message)}}
function showBookings(d,phone){let t=d.tenant;app.innerHTML=`<div class="public"><div class="book"><a href="/#book/${encodeURIComponent(t.slug)}" class="link">← Randevu al</a><header class="bookinghead" style="background:linear-gradient(135deg,${t.color||'#292b68'},#4f46e5)"><h1>Merhaba, ${esc(d.customer.name)}</h1><p>${esc(t.name)} · Randevularınızı buradan değiştirebilirsiniz.</p></header><section class="card bookingform"><div class="toolbar"><div><h2>Randevularım</h2><span class="sub">Telefon: ${esc(phone)}</span></div><button class="btn ghost" onclick="location.hash='#mine/${encodeURIComponent(t.slug)}'">Numarayı değiştir</button></div>${d.appointments.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Tarih</th><th>Saat</th><th>Hizmet</th><th>Uzman</th><th>Durum</th><th></th></tr></thead><tbody>${d.appointments.map(a=>`<tr><td>${dateTR(a.date)}</td><td><b>${a.time}</b></td><td>${esc(a.service)}</td><td>${esc(a.staff)}</td><td>${status(a.status)}</td><td class="actions">${a.status!=='cancelled'?`<button class="iconbtn" onclick="rescheduleModal('${t.slug}','${a.id}','${esc(phone)}')">Değiştir</button><button class="iconbtn" onclick="customerCancel('${t.slug}','${a.id}','${esc(phone)}')">İptal</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="sub">Bu numarada randevu yok.</p>'}</section></div></div>`}
function rescheduleModal(slug,id,phone){modal(`<h2>Randevuyu değiştir</h2><p>Seçtiğiniz yeni saat işletmenin onayına gönderilir.</p><form class="form" onsubmit="customerReschedule(event,'${esc(slug)}','${id}','${esc(phone)}')"><label class="field">Yeni tarih<input required type="date" min="${today}" name="date" value="${today}"></label><label class="field">Yeni saat<select name="time">${['09:00','09:30','10:00','10:30','11:00','11:30','13:00','13:30','14:00','14:30','15:00','15:30','16:00','16:30','17:00'].map(x=>`<option>${x}</option>`).join('')}</select></label><div class="modalfoot field full"><button type="button" class="btn ghost" onclick="closeModal()">Vazgeç</button><button class="btn">Değişiklik iste</button></div></form>`)}
async function customerCancel(slug,id,phone){await api(`public/${encodeURIComponent(slug)}/appointments/${id}`,'PATCH',{phone,status:'cancelled'});toast('Randevunuz iptal edildi.');let d=await api(`public/${encodeURIComponent(slug)}/customer?phone=${encodeURIComponent(phone)}`);showBookings(d,phone)}
async function customerReschedule(e,slug,id,phone){e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.phone=phone;try{await api(`public/${encodeURIComponent(slug)}/appointments/${id}`,'PATCH',o);closeModal();toast('Değişiklik talebiniz gönderildi.');let d=await api(`public/${encodeURIComponent(slug)}/customer?phone=${encodeURIComponent(phone)}`);showBookings(d,phone)}catch(x){toast(x.message)}}
async function publicBooking(e,id){e.preventDefault();let o=Object.fromEntries(new FormData(e.target)),exists=db.customers.find(c=>c.tenantId===id&&c.phone===o.phone);let cust=exists||await api(`tenant/${id}/customers`,'POST',{name:o.name,phone:o.phone,visits:0});let all=db.appointments.filter(a=>a.tenantId===id);if(all.some(a=>a.staffId===o.staffId&&a.date===o.date&&a.time===o.time&&a.status!=='cancelled'))return toast('Seçilen saat artık dolu; başka bir saat deneyin.');let mode=db.tenants.find(t=>t.id===id)?.appointmentApprovalMode||'manual';let ap=await api(`tenant/${id}/appointments`,'POST',{customerId:cust.id,staffId:o.staffId,serviceId:o.serviceId,date:o.date,time:o.time,status:mode==='auto'?'confirmed':'pending',note:'Online randevu talebi'});let t=db.tenants.find(x=>x.id===id),service=db.services.find(x=>x.id===o.serviceId),staff=db.staff.find(x=>x.id===o.staffId);bookingConfirmation(t,service,staff,ap)}
function bookingConfirmation(t,service,staff,ap){let detail={business:t.name,address:t.address||'Adres bilgisi işletmeden alınacaktır',phone:t.phone||'Telefon bilgisi yok',service:service?.name||'Hizmet',staff:staff?.name||'Çalışan',date:ap.date,time:ap.time};sessionStorage.setItem('dakikaProLastBooking',JSON.stringify(detail));app.innerHTML=`<div class="public"><div class="book"><header class="bookinghead" style="background:linear-gradient(135deg,${t.color||'#292b68'},#4f46e5)"><h1>Randevu talebiniz alındı</h1><p>İşletme onayladığında size bilgi verilecektir.</p></header><section class="card bookingform"><h2>${esc(detail.business)}</h2><div class="listitem"><span>Hizmet</span><b>${esc(detail.service)}</b></div><div class="listitem"><span>Çalışan</span><b>${esc(detail.staff)}</b></div><div class="listitem"><span>Tarih / saat</span><b>${dateTR(detail.date)} · ${detail.time}</b></div><div class="listitem"><span>Adres</span><b>${esc(detail.address)}</b></div><div class="listitem"><span>Telefon</span><b>${esc(detail.phone)}</b></div><div class="heroactions"><button class="btn" onclick="addToCalendar()">Takvimime ekle</button><button class="btn ghost" onclick="shareBooking()">WhatsApp'ta paylaş</button></div><p class="sub">WhatsApp mesajına randevu ve işletme bilgileriniz otomatik eklenir.</p><a class="link" href="/#mine/${encodeURIComponent(t.slug)}">Randevularımı yönet</a></section></div></div>`}
function lastBooking(){try{return JSON.parse(sessionStorage.getItem('dakikaProLastBooking'))}catch{return null}}
function addToCalendar(){let d=lastBooking();if(!d)return;let stamp=d.date.replaceAll('-','')+'T'+d.time.replace(':','')+'00',end=new Date(`${d.date}T${d.time}:00`);end.setMinutes(end.getMinutes()+60);let endStamp=end.toISOString().replace(/[-:]/g,'').replace('.000','');let ics=`BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//DakikaPro//TR\nBEGIN:VEVENT\nUID:${Date.now()}@dakikapro\nDTSTART:${stamp}\nDTEND:${endStamp}\nSUMMARY:${d.business} - ${d.service}\nDESCRIPTION:Çalışan: ${d.staff}\\nTelefon: ${d.phone}\nLOCATION:${d.address}\nEND:VEVENT\nEND:VCALENDAR`;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([ics],{type:'text/calendar;charset=utf-8'}));a.download='randevu.ics';a.click();URL.revokeObjectURL(a.href);toast('Takvim dosyası indirildi.')}
function shareBooking(){let d=lastBooking();if(!d)return;let text=`*${d.business} Randevu Bilgisi*\n\nHizmet: ${d.service}\nÇalışan: ${d.staff}\nTarih / Saat: ${dateTR(d.date)} · ${d.time}\nAdres: ${d.address}\nTelefon: ${d.phone}`;window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank','noopener');}
window.go=go;window.startTrial=startTrial;window.businessGo=businessGo;window.setAppointmentMode=setAppointmentMode;window.filterCustomers=filterCustomers;window.exportCustomers=exportCustomers;window.signup=signup;window.ownerLogin=ownerLogin;window.adminLogin=adminLogin;window.ownerLogout=ownerLogout;window.adminLogout=adminLogout;window.forgotPassword=forgotPassword;window.paymentRequest=paymentRequest;window.choosePlan=choosePlan;window.selectTenant=selectTenant;window.toggleTenant=toggleTenant;window.deleteTenant=deleteTenant;window.tenantModal=tenantModal;window.editTenantModal=editTenantModal;window.saveTenant=saveTenant;window.planModal=planModal;window.savePlan=savePlan;window.saveSettings=saveSettings;window.saveNotificationSettings=saveNotificationSettings;window.saveBusinessSettings=saveBusinessSettings;window.savePaymentSettings=savePaymentSettings;window.closeModal=closeModal;window.createTenant=createTenant;window.entityModal=entityModal;window.createEntity=createEntity;window.appointmentModal=appointmentModal;window.createAppointment=createAppointment;window.changeAppointment=changeAppointment;window.publicBooking=publicBooking;window.addToCalendar=addToCalendar;window.shareBooking=shareBooking;window.lookupBookings=lookupBookings;window.rescheduleModal=rescheduleModal;window.customerCancel=customerCancel;window.customerReschedule=customerReschedule;window.addEventListener('hashchange',render);reload().catch(e=>app.innerHTML=`<div class="public"><div class="book card"><h2>Bağlantı kurulamadı</h2><p>${esc(e.message)}</p></div></div>`);
